<?php
// Telegram bot tests (included by tests/run.php). The Bot API is a local mock (tests/telegram_mock.php); the AI is the scripted mock (MFNC_AI_MOCK=1).
$tgPort = 8097; $tgBase = "http://127.0.0.1:$tgPort"; putenv("TELEGRAM_API_BASE=$tgBase"); putenv('MFNC_AI_MOCK=1'); @unlink(sys_get_temp_dir() . '/mfnc_telegram_mock.json');
$tgProc = proc_open([PHP_BINARY, '-S', "127.0.0.1:$tgPort", __DIR__ . '/telegram_mock.php'], [1 => ['file', '/dev/null', 'w'], 2 => ['file', '/dev/null', 'w']], $tgp);
for ($i = 0; $i < 40; $i++) { $fp = @fsockopen('127.0.0.1', $tgPort, $en, $es, 0.2); if ($fp) { fclose($fp); break; } usleep(100000); }
$TOKEN = '123456789:AAtest_token_for_unit_tests_12345'; $SECRET = 'whsec_tg_unit_test_secret_value_0123456789'; $T_CHAT_A = 5550001; $T_CHAT_B = 5550002; $T_UID = 9000; $tgCfg = $cfgSet;
$tgHttp = function (string $path, string $body = '') use ($tgBase) { $c = stream_context_create(['http' => ['method' => $body === '' ? 'GET' : 'POST', 'content' => $body, 'timeout' => 10, 'ignore_errors' => true]]); return (string) @file_get_contents($tgBase . $path, false, $c); };
$tgReset = function () use ($tgHttp) { $tgHttp('/__reset', 'x'); run('UPDATE {telegram_log} SET created_at = DATE_SUB(created_at, INTERVAL 3 DAY) WHERE created_at > DATE_SUB(UTC_TIMESTAMP(), INTERVAL 2 DAY)'); }; // old rows stay for the log checks but stop counting toward rate limits
$tgCalls = function (?string $method = null) use ($tgHttp) { $all = json_decode($tgHttp('/__calls'), true) ?: []; return $method === null ? $all : array_values(array_filter($all, fn($c) => $c['method'] === $method)); };
$tgMsgs = fn() => array_values(array_filter($tgCalls(), fn($c) => in_array($c['method'], ['sendMessage', 'sendPhoto', 'editMessageText'], true) && empty($c['error'])));
$tgLast = function () use ($tgMsgs) { $m = $tgMsgs(); return $m ? end($m) : null; };
$tgText = fn(?array $c) => $c ? (string) ($c['params']['text'] ?? $c['params']['caption'] ?? '') : '';
$tgBtns = function (?array $c) { $o = []; foreach (($c['params']['reply_markup']['inline_keyboard'] ?? []) as $row) { foreach ($row as $b) { $o[] = $b; } } return $o; };
$tgFind = function (?array $c, string $needle) use ($tgBtns) { foreach ($tgBtns($c) as $b) { if (stripos($b['text'], $needle) !== false) { return $b; } } return null; };
$tgUid = 100;
$tgUpdate = function (int $chat, string $text, array $extra = []) use (&$tgUid) { return ['update_id' => ++$tgUid, 'message' => ['message_id' => $tgUid, 'date' => time(), 'chat' => ['id' => $chat, 'type' => 'private'], 'from' => ['id' => $chat, 'is_bot' => false, 'first_name' => 'Asha', 'username' => 'asha_t'], 'text' => $text] + $extra]; };
$tgCb = function (int $chat, string $data, int $mid = 77) use (&$tgUid) { return ['update_id' => ++$tgUid, 'callback_query' => ['id' => 'cbq' . $tgUid, 'from' => ['id' => $chat, 'is_bot' => false, 'first_name' => 'Asha'], 'message' => ['message_id' => $mid, 'chat' => ['id' => $chat, 'type' => 'private']], 'data' => $data]]; };
$tgSend = function (array $upd, ?string $secret = null, array $hdr = []) use (&$SECRET) { $h = $hdr ?: ['X-Telegram-Bot-Api-Secret-Token' => $secret ?? $SECRET]; [$code, $msg, $u] = tg_webhook_accept(json_encode($upd), $h); if ($u) { tg_process_update($u); } return $code; };
$tgSay = function (int $chat, string $text, array $extra = []) use ($tgUpdate, $tgSend) { return $tgSend($tgUpdate($chat, $text, $extra)); };
$tgBalance = fn(int $uid, int $acc) => (int) array_column(load_snapshot($uid)['accounts'], 'balance', 'id')[$acc];
$tgTx = fn(int $uid) => (int) val('SELECT COUNT(*) FROM {transactions} WHERE user_id=?', [$uid]);
$tgLink = function (int $uid, int $chat) use ($tgSay) { $t = tg_link_token_create($uid); $tgSay($chat, '/start ' . $t['token']); return $t; };

section('telegram: config, secrets and the Bot API client');
check('token format', tg_token_ok($TOKEN) && !tg_token_ok('nope') && !tg_token_ok('123:short')); check('username format', tg_username_ok('MomsFinanceBot') && !tg_username_ok('ab') && !tg_username_ok('has space'));
secret_set('tg_bot_token', $TOKEN); secret_set('tg_webhook_secret', $SECRET); $tgCfg(['tg_enabled' => '1', 'tg_bot_username' => 'MockFinanceBot', 'tg_notify' => '1', 'tg_rate_min' => '100', 'tg_rate_day' => '5000']);
check('token is encrypted at rest', !str_contains(site_setting('tg_bot_token'), '123456789') && str_starts_with(site_setting('tg_bot_token'), 'v1:')); check('webhook secret is encrypted at rest', !str_contains(site_setting('tg_webhook_secret'), 'whsec'));
putenv('TELEGRAM_BOT_TOKEN=999999999:AAenv_override_token_value_1234567'); eq(tg_cfg()['token'], '999999999:AAenv_override_token_value_1234567', 'TELEGRAM_BOT_TOKEN overrides the stored token'); putenv('TELEGRAM_BOT_TOKEN');
eq(tg_cfg()['base'], $tgBase, 'TELEGRAM_API_BASE is honoured'); putenv('TELEGRAM_API_BASE'); eq(tg_cfg()['base'], 'https://api.telegram.org', 'default API base is api.telegram.org'); putenv("TELEGRAM_API_BASE=$tgBase");
check('configured and ready', tg_configured() && tg_ready()); eq(tg_webhook_url(), 'https://finance.test/webhooks/telegram', 'webhook URL comes from APP_URL');
$me = tg_api('getMe'); eq($me['result']['username'], 'MockFinanceBot', 'getMe works against the mock');
secret_set('tg_bot_token', '123456789:AAx'); $msg = ''; try { tg_api('getMe'); } catch (Throwable $e) { $msg = $e->getMessage(); } secret_set('tg_bot_token', $TOKEN); check('a missing/invalid token never reaches the API', str_contains($msg, 'token is not set'));
check('mask_secret never shows the whole token', !str_contains(mask_secret($TOKEN), 'AAtest')); check('errors are scrubbed of the token', !str_contains(tg_scrub("fail $TOKEN end", $TOKEN), $TOKEN));

section('telegram: webhook secret, size, idempotency');
$base = ['update_id' => 1, 'message' => ['message_id' => 1, 'chat' => ['id' => 42, 'type' => 'private'], 'from' => ['id' => 42, 'is_bot' => false], 'text' => 'hi']];
eq(tg_webhook_accept(json_encode($base), ['X-Telegram-Bot-Api-Secret-Token' => 'wrong'])[0], 403, 'wrong secret is refused'); eq(tg_webhook_accept(json_encode($base), [])[0], 403, 'missing secret header is refused'); eq(tg_webhook_accept(json_encode($base), ['X-Telegram-Bot-Api-Secret-Token' => ''])[0], 403, 'empty secret header is refused');
eq(tg_webhook_accept(json_encode($base), ['X-TELEGRAM-BOT-API-SECRET-TOKEN' => $SECRET])[0], 200, 'the header name is case-insensitive (as index.php passes it)'); eq(tg_webhook_accept(json_encode($base), ['X-Telegram-Bot-Api-Secret-Token' => $SECRET . 'x'])[0], 403, 'a longer secret that starts the same is refused');
eq(tg_webhook_accept(json_encode(['update_id' => 2, 'pad' => str_repeat('x', TG_MAX_BODY)]), ['X-Telegram-Bot-Api-Secret-Token' => $SECRET])[0], 413, 'oversized bodies are refused'); [$c, $m, $u] = tg_webhook_accept('{not json', ['X-Telegram-Bot-Api-Secret-Token' => $SECRET]); check('garbage JSON gets a quiet 200 and no work', $c === 200 && $u === null && $m === 'ok');
[$c, $m, $u] = tg_webhook_accept(json_encode(['update_id' => 'abc']), ['X-Telegram-Bot-Api-Secret-Token' => $SECRET]); check('a non-integer update_id is ignored', $c === 200 && $u === null);
[$c, $m, $u1] = tg_webhook_accept(json_encode(['update_id' => 777001]), ['X-Telegram-Bot-Api-Secret-Token' => $SECRET]); [$c, $m, $u2] = tg_webhook_accept(json_encode(['update_id' => 777001]), ['X-Telegram-Bot-Api-Secret-Token' => $SECRET]); check('first delivery is processed, the repeat (same update_id) is not', $u1 !== null && $u2 === null && $c === 200);
$tgCfg(['tg_enabled' => '0']); [$c, $m, $u] = tg_webhook_accept(json_encode(['update_id' => 777002]), ['X-Telegram-Bot-Api-Secret-Token' => $SECRET]); check('bot switched off: quiet 200, nothing processed', $c === 200 && $u === null); $tgCfg(['tg_enabled' => '1']);
$tgReset(); $upd = $tgUpdate(31337, 'hello'); $tgSend($upd); $n1 = count($tgMsgs()); $tgSend($upd); eq(count($tgMsgs()), $n1, 'a replayed update is not answered twice');
$tgReset(); $tgSend($tgUpdate(31337, 'x'), 'wrong'); eq(count($tgCalls()), 0, 'a forged request triggers no outgoing calls');

section('telegram: deep-link token lifecycle');
$U1 = create_user('tg1@x.test', 'Asha Rao', 'password-12345'); $U2 = create_user('tg2@x.test', 'Bhavna Rao', 'password-12345'); load_demo_data($U1); load_demo_data($U2); $u1 = tg_user($U1); $u2 = tg_user($U2);
$t = tg_link_token_create($U1); check('token is long and URL-safe', (bool) preg_match('/^[A-Za-z0-9_-]{32}$/', $t['token'])); eq($t['link'], 'https://t.me/MockFinanceBot?start=' . $t['token'], 'deep link uses the bot username');
check('only a hash is stored', (int) val('SELECT COUNT(*) FROM {telegram_tokens} WHERE token_hash=?', [$t['token']]) === 0 && (int) val('SELECT COUNT(*) FROM {telegram_tokens} WHERE token_hash=?', [hash('sha256', $t['token'])]) === 1);
$ttl = (int) val('SELECT TIMESTAMPDIFF(MINUTE, UTC_TIMESTAMP(), expires_at) FROM {telegram_tokens} WHERE user_id=?', [$U1]); check('it expires in 15 minutes', $ttl >= 14 && $ttl <= 15, "(got $ttl)");
$t2 = tg_link_token_create($U1); eq(tg_link_consume($t['token'], $T_CHAT_A)['code'], 'invalid', 'asking for a new token invalidates the previous one'); $t = $t2;
$bad = ['short', '', str_repeat('a', 70), "bad token with spaces!!!!!!!!!!!", str_repeat('A', 32)]; foreach ($bad as $b) { eq(tg_link_consume($b, $T_CHAT_A)['code'], 'invalid', 'invalid token rejected: ' . substr($b, 0, 12)); }
$r = tg_link_consume($t['token'], $T_CHAT_A, ['first_name' => 'Asha', 'username' => 'asha_t']); check('a valid token links', $r['ok'] && $r['user_id'] === $U1); eq(tg_link_by_chat($T_CHAT_A)['user_id'], $U1, 'chat is linked to the user');
eq(tg_link_consume($t['token'], $T_CHAT_A)['code'], 'used', 'a token is single-use'); eq(tg_link_consume($t['token'], $T_CHAT_B)['code'], 'used', '...even from another chat');
$e = tg_link_token_create($U2); run('UPDATE {telegram_tokens} SET expires_at = DATE_SUB(UTC_TIMESTAMP(), INTERVAL 1 MINUTE) WHERE user_id=?', [$U2]); eq(tg_link_consume($e['token'], $T_CHAT_B)['code'], 'expired', 'an expired token is refused'); eq(tg_link_by_chat($T_CHAT_B), null, 'and nothing was linked');
$w = tg_link_token_create($U2); $r = tg_link_consume($w['token'], $T_CHAT_A); eq($r['code'], 'chat_taken', "a chat already linked to someone else cannot take another person's token"); eq((int) val('SELECT COUNT(*) FROM {telegram_tokens} WHERE token_hash=? AND used_at IS NULL', [hash('sha256', $w['token'])]), 1, 'that token stays unused'); eq(tg_link_for($U2), null, 'the second user stays unlinked');
$r = tg_link_consume($w['token'], $T_CHAT_B); check('the right chat still works with it', $r['ok']); eq(tg_link_for($U2)['chat_id'], $T_CHAT_B, 'user 2 is linked to chat B');
$x = tg_link_token_create($U1); $r = tg_link_consume($x['token'], 5550003); check('one chat per user: relinking moves the account and reports the old chat', $r['ok'] && $r['old_chat'] === $T_CHAT_A); eq((int) val('SELECT COUNT(*) FROM {telegram_links} WHERE user_id=?', [$U1]), 1, 'still one row'); eq(tg_link_by_chat($T_CHAT_A), null, 'old chat is free again');
$x = tg_link_token_create($U1); tg_link_consume($x['token'], $T_CHAT_A); $thrown = false; try { run('INSERT INTO {telegram_links} (user_id,chat_id) VALUES (?,?)', [$U2, $T_CHAT_A]); } catch (PDOException) { $thrown = true; } check('the database refuses two users on one chat (unique constraint)', $thrown);
$thrown = false; try { run('UPDATE {telegram_links} SET chat_id=? WHERE user_id=?', [$T_CHAT_A, $U2]); } catch (PDOException) { $thrown = true; } check('...and cannot be moved onto an existing chat', $thrown);
run('UPDATE {users} SET status=? WHERE id=?', ['disabled', $U2]); tg_unlink($U2, false); $d = tg_link_token_create($U2); eq(tg_link_consume($d['token'], $T_CHAT_B)['code'], 'disabled', 'a disabled account cannot link'); run('UPDATE {users} SET status=? WHERE id=?', ['active', $U2]);
eq(tg_link_token_create($U2)['token'] === $d['token'], false, 'new tokens are random');

section('telegram: /start and /stop through the webhook');
$tgReset(); tg_unlink($U1, false); tg_unlink($U2, false);
$tgSay($T_CHAT_A, 'hello'); $m = $tgLast(); check('an unknown chat is told how to connect', str_contains($tgText($m), 'Connect Telegram'));
$tgSay($T_CHAT_A, '/start'); check('/start without a token explains too', str_contains($tgText($tgLast()), 'Connect Telegram'));
$tgSay($T_CHAT_A, '/start ' . str_repeat('z', 32)); check('a made-up token gets a friendly refusal', str_contains($tgText($tgLast()), 'does not look right'));
$tk = tg_link_token_create($U1); $tgReset(); $tgSay($T_CHAT_A, '/start ' . $tk['token']); $m = $tgLast(); check('a valid /start connects and welcomes the person', str_contains($tgText($m), 'You are connected, Asha') && tg_link_by_chat($T_CHAT_A) !== null);
check('the welcome shows the reply keyboard', isset($m['params']['reply_markup']['keyboard']) && count($m['params']['reply_markup']['keyboard']) === 2); eq(tg_link_by_chat($T_CHAT_A)['tg_username'], 'asha_t', 'telegram username is recorded');
$tgReset(); $tgSay($T_CHAT_A, '/start ' . $tk['token']); check('reusing the link says it was used', str_contains($tgText($tgLast()), 'already used'));
$tk2 = tg_link_token_create($U2); $tgReset(); $tgSay($T_CHAT_A, '/start ' . $tk2['token']); check("another person's token from a connected chat is refused", str_contains($tgText($tgLast()), 'already connected to another') && tg_link_for($U2) === null);
$tgReset(); $tgSay($T_CHAT_A, '/stop'); check('/stop disconnects and confirms', tg_link_by_chat($T_CHAT_A) === null && str_contains($tgText($tgLast()), 'disconnected')); eq((int) val('SELECT COUNT(*) FROM {telegram_links} WHERE user_id=?', [$U1]), 0, 'link row is gone');
$tgLink($U1, $T_CHAT_A); $tgReset(); check('disconnecting from the app tells the chat', tg_unlink($U1, true, 'app') && str_contains($tgText($tgLast()), 'disconnected') && tg_link_for($U1) === null);
$tgLink($U1, $T_CHAT_A); $tgLink($U2, $T_CHAT_B); check('both people are connected to their own chats', tg_link_by_chat($T_CHAT_A)['user_id'] === $U1 && tg_link_by_chat($T_CHAT_B)['user_id'] === $U2);

section('telegram: basic commands');
$acc1 = (int) val('SELECT id FROM {accounts} WHERE user_id=? AND archived=0 ORDER BY id LIMIT 1', [$U1]); run('UPDATE {accounts} SET name=? WHERE id=?', ['Evil <b>&</b> Bank', $acc1]);
$tgReset(); $tgSay($T_CHAT_A, '/balance'); $m = $tgLast(); $tx = $tgText($m); check('/balance shows total cash and accounts (HTML-escaped)', str_contains($tx, 'Total cash') && str_contains($tx, 'Evil &lt;b&gt;&amp;&lt;/b&gt; Bank') && !str_contains($tx, 'Evil <b>')); check('the mock accepted the HTML (valid entities and tags)', empty($tgCalls('sendMessage')[0]['error'] ?? null));
$tgReset(); $tgSay($T_CHAT_A, '/bills'); $m = $tgLast(); $mp = $tgFind($m, 'Mark paid'); check('/bills lists due bills with Mark paid buttons', str_contains($tgText($m), 'Due soon') && $mp !== null); check('callback data is short and signed for this chat and user', strlen($mp['callback_data']) <= 64 && tg_cb_parse($T_CHAT_A, $U1, $mp['callback_data'])[0] === 'mp' && tg_cb_parse($T_CHAT_B, $U1, $mp['callback_data']) === null && tg_cb_parse($T_CHAT_A, $U2, $mp['callback_data']) === null);
$tgReset(); $tgSay($T_CHAT_A, '/goals'); check('/goals shows progress bars', str_contains($tgText($tgLast()), '▰') || str_contains($tgText($tgLast()), 'no goals'));
$tgReset(); $tgSay($T_CHAT_A, '/report'); $tx = $tgText($tgLast()); check('/report summarises the month', str_contains($tx, 'Income') && str_contains($tx, 'Spent') && str_contains($tx, 'Saved'));
$tgReset(); $tgSay($T_CHAT_A, '/help'); check('/help lists the commands', str_contains($tgText($tgLast()), '/balance') && str_contains($tgText($tgLast()), '/bills')); $tgReset(); $tgSay($T_CHAT_A, '/menu'); check('/menu is an inline keyboard', count($tgBtns($tgLast())) === 6);
$tgReset(); $tgSay($T_CHAT_A, '/nonsense'); check('unknown commands get a pointer to /help', str_contains($tgText($tgLast()), '/help')); $tgReset(); $tgSay($T_CHAT_A, '💰 Balance'); check('reply-keyboard labels work like commands', str_contains($tgText($tgLast()), 'Total cash'));
$tgReset(); $tgSay($T_CHAT_A, '/balance@MockFinanceBot'); check('commands addressed to the bot by name work', str_contains($tgText($tgLast()), 'Total cash'));
$tgReset(); $menu = $tgFind((function () use ($tgSay, $tgLast, $T_CHAT_A) { $tgSay($T_CHAT_A, '/menu'); return $tgLast(); })(), 'Balance'); $tgReset(); $tgSend($tgCb($T_CHAT_A, $menu['callback_data'])); check('menu buttons run the command and answer the callback', str_contains($tgText($tgLast()), 'Total cash') && count($tgCalls('answerCallbackQuery')) === 1);
run('UPDATE {accounts} SET name=? WHERE id=?', ['HDFC Savings', $acc1]);
$tgReset(); $tgSay($T_CHAT_A, '/notify on'); eq(tg_link_for($U1)['notify'], 1, '/notify on opts in'); $tgSay($T_CHAT_A, '/notify off'); eq(tg_link_for($U1)['notify'], 0, '/notify off opts out'); $tgSay($T_CHAT_A, '/notify'); check('/notify shows the state', str_contains($tgText($tgLast()), 'off'));
$tgCfg(['tg_notify' => '0']); $tgReset(); $tgSay($T_CHAT_A, '/notify on'); check('the admin switch beats /notify on', str_contains($tgText($tgLast()), 'switched off') && tg_link_for($U1)['notify'] === 0); $tgCfg(['tg_notify' => '1']);

section('telegram: "spent 450 on groceries" (parser, confirm, undo)');
$P = fn($t) => tg_parse_entry($t, '2026-10-21');
eq($P('spent 450 on groceries'), ['type' => 'expense', 'amount' => 45000, 'desc' => 'groceries', 'date' => '2026-10-21'], 'simple expense'); eq($P('450 groceries')['amount'], 45000, 'number then words is an expense'); eq($P('paid ₹1,200.50 for electricity yesterday'), ['type' => 'expense', 'amount' => 120050, 'desc' => 'electricity', 'date' => '2026-10-20'], 'rupee sign, commas, paise, yesterday');
eq($P('received 5000 salary')['type'], 'income', 'received = income'); eq($P('+250 refund from Amazon')['type'], 'income', '+ means income'); eq($P('spent 2k on fuel')['amount'], 200000, '2k = 2,000'); eq($P('Rs. 99 on tea')['amount'], 9900, 'Rs. prefix');
eq($P('hello there'), null, 'chat is not an entry'); eq($P('450'), null, 'a bare number is not an entry'); eq($P('spent on groceries'), null, 'no amount'); eq($P('spent 0 on x'), null, 'zero is refused'); eq($P('spent 99999999999999 on x'), null, 'absurd amounts are refused'); eq($P(str_repeat('a', 300)), null, 'overlong text is refused');
check('guessing a category from words', tg_guess_category(load_snapshot($U1), 'expense', 'groceries') !== null);
$accE = (int) tg_default_account(load_snapshot($U1), 'expense')['id']; $b0 = $tgBalance($U1, $accE); $n0 = $tgTx($U1); $tgReset(); $tgSay($T_CHAT_A, 'spent 450 on groceries'); $m = $tgLast(); $tx = $tgText($m);
check('a confirmation is shown first', str_contains($tx, 'Add this?') && str_contains($tx, '₹450') && str_contains($tx, 'groceries')); eq($tgTx($U1), $n0, 'nothing is written before the tap'); eq($tgBalance($U1, $accE), $b0, 'balance unchanged before the tap');
$ok = $tgFind($m, 'Add it'); $cx = $tgFind($m, 'Cancel'); check('confirm and cancel buttons carry signed data', $ok && $cx && tg_cb_parse($T_CHAT_A, $U1, $ok['callback_data']) !== null);
$tamper = substr($ok['callback_data'], 0, -1) . (substr($ok['callback_data'], -1) === 'a' ? 'b' : 'a'); $tgReset(); $tgSend($tgCb($T_CHAT_A, $tamper)); eq($tgTx($U1), $n0, 'a tampered button does nothing'); check('...and the person is told', str_contains((string) ($tgCalls('answerCallbackQuery')[0]['params']['text'] ?? ''), 'no longer valid'));
$tgReset(); $tgSend($tgCb($T_CHAT_B, $ok['callback_data'])); eq($tgTx($U1), $n0, "someone else's chat cannot press my button"); $tgSend($tgCb(5559999, $ok['callback_data'])); eq($tgTx($U1), $n0, 'an unconnected chat cannot press it either');
$tgReset(); $tgSend($tgCb($T_CHAT_A, $ok['callback_data'])); $acct = $tgCalls('answerCallbackQuery'); eq($tgTx($U1), $n0 + 1, 'confirming adds exactly one transaction'); eq($tgBalance($U1, $accE) - $b0, -45000, 'and the balance moves by the confirmed amount');
$row = one('SELECT * FROM {transactions} WHERE user_id=? ORDER BY id DESC LIMIT 1', [$U1]); check('the entry has the right type, amount and description', $row['type'] === 'expense' && (int) $row['amount'] === 45000 && $row['description'] === 'groceries'); check('it was written to the audit log', (int) val("SELECT COUNT(*) FROM {audit_log} WHERE action='telegram.entry'") === 1);
$res = $tgLast(); $undo = $tgFind($res, 'Undo'); check('the result offers Undo', $undo !== null && str_contains($tgText($res), 'Added')); $tgSend($tgCb($T_CHAT_A, $ok['callback_data'])); eq($tgTx($U1), $n0 + 1, 'a double tap does not post twice');
$tgReset(); $tgSend($tgCb($T_CHAT_A, $undo['callback_data'])); eq($tgTx($U1), $n0, 'Undo removes it'); eq($tgBalance($U1, $accE), $b0, 'and restores the balance'); $tgSend($tgCb($T_CHAT_A, $undo['callback_data'])); check('undo cannot run twice', str_contains((string) ($tgCalls('answerCallbackQuery')[1]['params']['text'] ?? ''), 'Nothing to undo'));
$tgReset(); $tgSay($T_CHAT_A, 'spent 100 on tea'); $m = $tgLast(); $tgReset(); $tgSend($tgCb($T_CHAT_A, $tgFind($m, 'Cancel')['callback_data'])); eq($tgTx($U1), $n0, 'cancel writes nothing'); check('and says so', str_contains($tgText($tgLast()), 'Cancelled'));
$tgReset(); $tgSay($T_CHAT_A, '/add'); check('/add alone asks what happened', str_contains($tgText($tgLast()), 'spent 450')); $tgSay($T_CHAT_A, 'received 7000 freelance'); $m = $tgLast(); check('the next message completes the guided add', str_contains($tgText($m), 'Income') && str_contains($tgText($m), '7,000'));
$tgReset(); $tgSay($T_CHAT_A, '/add'); $tgSay($T_CHAT_A, 'blah blah'); check('an unreadable answer is explained', str_contains($tgText($tgLast()), 'could not read')); $tgReset(); $tgSay($T_CHAT_A, '/add spent 30 on chai'); check('/add with text goes straight to confirmation', str_contains($tgText($tgLast()), 'Add this?'));
$tgReset(); $tgSay($T_CHAT_A, 'spent 77 on <script>alert(1)</script>'); $m = $tgLast(); check('typed HTML is escaped in the confirmation', str_contains($tgText($m), '&lt;script&gt;') && empty($tgCalls('sendMessage')[0]['error'] ?? null));
