section('telegram: reminders (opt-in, once, templates)');
run('UPDATE {telegram_links} SET notify=0'); $tgReset(); $n = tg_send_due_reminders(); eq($n, 0, 'nobody opted in: nothing is sent'); eq(count($tgMsgs()), 0, 'no messages at all');
run('UPDATE {telegram_links} SET notify=1 WHERE user_id=?', [$U1]); run("DELETE FROM {telegram_sent}"); $due = array_filter(occurrence_views(load_snapshot($U1)), fn($v) => !$v['skipped'] && $v['outstanding'] > 0 && ($v['overdue'] || $v['days'] <= 7)); $tgReset(); $n = tg_send_due_reminders();
check('an opted-in person is reminded about bills due soon or overdue', $due ? ($n > 0 && count($tgMsgs()) === $n) : true, "(n=$n, due=" . count($due) . ')'); if ($n) { $m = $tgMsgs()[0]; check('the reminder has a Mark paid button', $tgFind($m, 'Mark paid') !== null); check('and fills the template parameters', !str_contains($tgText($m), '{') && str_contains($tgText($m), '₹')); }
$tgReset(); eq(tg_send_due_reminders(), 0, 'the same reminders are never sent twice'); run('UPDATE {telegram_links} SET notify=1 WHERE user_id=?', [$U2]); $cfgSet(['tg_notify' => '0']); run('DELETE FROM {telegram_sent}'); eq(tg_send_due_reminders(), 0, 'the admin switch turns reminders off'); $cfgSet(['tg_notify' => '1']);
$_POST = ['tpl' => ['bill.due' => 'Hey {name}, {nope} {title}']]; throws(fn() => do_admin_telegram_templates($admU), 'Unknown parameter', 'unknown template parameters are rejected'); $_POST = ['tpl' => ['bill.due' => 'Yo {name}: {title} {amount} on {due_date}']]; do_admin_telegram_templates($admU); eq(tg_template('bill.due'), 'Yo {name}: {title} {amount} on {due_date}', 'a custom template is stored'); $_POST = ['reset' => 'bill.due']; do_admin_telegram_templates($admU); eq(tg_template('bill.due'), tg_default_template('bill.due'), 'and can be reset'); $_POST = [];
$tgReset(); $ch = admin_create_charge($ADM, $U1, 'Telegram charge', null, 25000, day_after_n(today(), 5)); $mm = $tgLast(); check('a new charge reaches an opted-in person in Telegram', $mm && str_contains($tgText($mm), 'Telegram charge') && str_contains($tgText($mm), '₹250')); $tgReset(); notify_charge($U1, $ch, 'new'); eq(count($tgMsgs()), 0, '...once');

